      title: 'Sommige recente afdrukken konden niet met miniaturen worden gearchiveerd',
      body: 'De slicer heeft het .gcode.3mf-bestand niet op de SD-kaart van de printer achtergelaten, waardoor Bambuddy de miniatuur of slicermetadata niet kon ophalen. Dit komt meestal doordat "Verzonden bestanden opslaan op externe opslag" is uitgeschakeld in de slicer (tabblad Apparaat in Bambu Studio / OrcaSlicer).',
      docsLink: 'Zie installatiestap 4',
      dismissLabel: 'Deze melding sluiten',
      docsLinkInternalStorage: 'Waarom dit gebeurt',
      titleInternalStorage: 'Sommige recente afdrukken bleven op de interne opslag van de printer staan',
      bodyInternalStorage: 'Bambu Studio plaatste het geslicede bestand op de interne opslag van de printer in plaats van op de kaart, waardoor Bambuddy via FTP niets kon uitlezen. Op H2-serie en P2S doet de knop Afdrukken dit altijd — alleen Verzenden biedt een keuze, en ook daar is Cache standaard. Die afdrukken worden nog steeds gearchiveerd met naam en timing, maar zonder miniatuur of slicermetadata. Voor volledige archieven start je de afdruk vanuit Bambuddy, slice je in OrcaSlicer, of gebruik je in Bambu Studio Verzenden met Extern geselecteerd en start je daarna de afdruk. Voor al deze opties is een kaart of USB-stick in de printer nodig.',
      titleNoExternalStorage: 'Sommige recente afdrukken konden niet worden gearchiveerd — geen opslag in de printer',
      bodyNoExternalStorage: 'De printer meldt dat er geen kaart of USB-stick in de sleuf zit, waardoor het geslicede bestand nergens kon worden opgeslagen en Bambuddy niets kon uitlezen. Plaats er een en de volgende afdruk wordt volledig gearchiveerd.',
      titleInternalHistory: 'Sommige recente prints zijn gestart vanaf een bestand dat al op de printer stond',
      bodyInternalHistory: 'Die prints liepen vanuit de eigen bibliotheek van de printer — opnieuw afdrukken via het scherm, starten vanuit Handy, of een bestand dat eerder is verstuurd en later is afgedrukt. Bambuddy leest printbestanden via FTP, dat alleen de kaart of stick aanbiedt, terwijl de printer die bibliotheek bewaart op een plek die FTP niet kan bereiken. Er was dus geen 3MF om te lezen. Geen enkele slicer-instelling verandert dit, omdat er voor deze prints niets is verstuurd. Ze worden nog steeds gearchiveerd met naam en tijden, en via Archief bewerken kun je het gebruikte filament handmatig invullen. Start de print vanuit Bambuddy of vanuit je slicer voor een volledig archief.',
